script.inlineScript:
/**
  * @param {params} params
  * @param {api} params.api
  * @param {any} params.imports
  */
function evaluateProperty({api}) {
  return {"aria-label":api.context.props.backButtonAriaLabel};
}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {any} params.imports
  */
function evaluateProperty({api}) {
  if(api.state.selectedTable === "" || api.state.selectedTable === null)
    return true;
  return false;
}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
  if (api.state.searchDisabled)
    return  [{"status":"suggestion","icon":"circle-info-outline","content": api.state.searchNotAvailableText}];
  return [];
}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {any} params.imports
  */
function evaluateProperty({api}) {
  if(api.state.selectedId)
    return [api.state.selectedId];
  return [];
}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {any} params.imports
  */
function evaluateProperty({api}) {
	return !api.state.canCreate;
}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {any} params.imports
  */
function evaluateProperty({api}) {
	if(api.state.canCreate)
    return api.state.createText + '';
  return api.state.cannotCreateText + '';
}
